<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);$config=require $root.'/config/config.php';require $root.'/app/Core/Bootstrap.php';require $root.'/app/Core/Database.php';
date_default_timezone_set($config['app']['timezone']);
spl_autoload_register(function($class)use($root){foreach(array('/app/Core/','/app/Services/')as$directory){$path=$root.$directory.$class.'.php';if(is_file($path)){require_once $path;return;}}});
$pdo=Database::connect($config);$outbox=new NotificationOutboxService($pdo);$wecom=new WeComWebhookService($pdo,$config);$email=new EmailService($pdo,$config);foreach($outbox->claim(20) as $row){try{$payload=json_decode($row['payload_json'],true);if(!is_array($payload))throw new RuntimeException('通知内容无效。');if($row['channel']==='email'){if($email->send(isset($payload['to'])?$payload['to']:'',isset($payload['subject'])?$payload['subject']:'',isset($payload['body'])?$payload['body']:'')===false)throw new RuntimeException('SMTP 未启用。');}elseif($row['channel']==='wecom')$wecom->sendPayload(array_merge($payload,array('event_type'=>$row['event_type'])));else throw new RuntimeException('通知渠道无效。');$outbox->sent($row['id']);echo 'sent '.$row['id'].' '.$row['event_type']."\n";}catch(Exception $e){$message=$e->getMessage();$retryable=strpos($message,'网络')!==false||strpos($message,'TLS 握手')!==false||preg_match('/HTTP 5[0-9]{2}/',$message)===1;$outbox->failed($row['id'],$e->getMessage(),$retryable);echo 'failed '.$row['id'].' '.$row['event_type']."\n";}}
